contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test function
    function run(uint256 amount, bool doWithdraw) public payable {
        require(address(this).balance >= amount);

        // read balance before
        uint256 beforeUser = c.getBalance(address(this));
        uint256 beforeContractEth = address(c).balance;

        // perform addToBalance sending `amount` wei
        bool addReverted;
        try c.addToBalance{value: amount}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        // read after add attempt
        uint256 afterUser = c.getBalance(address(this));
        uint256 afterContractEth = address(c).balance;

        // optionally attempt withdraw
        bool withdrawReverted = false;
        uint256 afterWithdrawUser = afterUser;
        uint256 afterWithdrawContractEth = afterContractEth;
        uint256 afterThisBalance = address(this).balance;

        if (doWithdraw) {
            // try to withdraw; capture revert
            try c.withdrawBalance() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
            // read post-withdraw state
            afterWithdrawUser = c.getBalance(address(this));
            afterWithdrawContractEth = address(c).balance;
            afterThisBalance = address(this).balance;
        }

        // General rule asserted:
        // 1) If addToBalance did not revert, then the stored user balance increased exactly by amount
        //    and the contract's ETH balance increased by amount.
        // 2) If addToBalance reverted, nothing changed.
        // 3) If withdraw was attempted and did not revert, the user balance becomes zero and the
        //    contract's ETH decreased by the withdrawn amount (which equals the previous stored balance),
        //    and this contract's balance increased by that same amount.
        assert(
            (
                (!addReverted) &&
                (afterUser == beforeUser + amount) &&
                (afterContractEth == beforeContractEth + amount) &&
                (
                    (!doWithdraw) || (
                        // withdraw attempted and must succeed: then afterWithdrawUser==0 and contract eth decreased by previous stored amount
                        (!withdrawReverted) &&
                        (afterWithdrawUser == 0) &&
                        (afterWithdrawContractEth + (beforeUser + amount) == afterContractEth + 0) &&
                        // this contract gained the withdrawn amount
                        (afterThisBalance >= address(this).balance - 0) // trivial placeholder to allow reading balance; actual transfer checked via balances relation above
                    )
                )
            )
            ||
            (
                (addReverted) &&
                (afterUser == beforeUser) &&
                (afterContractEth == beforeContractEth) &&
                // if withdraw attempted but nothing to withdraw, withdraw may still revert or succeed (but balance zero)
                (!doWithdraw || (afterWithdrawUser == beforeUser && afterWithdrawContractEth == beforeContractEth))
            )
        );
    }

    // accept ETH when C sends funds back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test function
    function run(uint256 amount) public payable {
        // to send Ether, require the test contract has enough balance
        require(address(this).balance >= amount);

        // read balances before
        uint256 beforeUser = c.getBalance(address(this));
        uint256 beforeContractEth = address(c).balance;

        // attempt to add to balance and capture whether it reverted
        bool addReverted;
        try c.addToBalance{value: amount}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        // read balances after the add attempt
        uint256 afterUser = c.getBalance(address(this));
        uint256 afterContractEth = address(c).balance;

        // General invariant:
        // - If the add did not revert: afterUser == beforeUser + amount AND afterContractEth == beforeContractEth + amount
        // - If the add reverted: afterUser == beforeUser AND afterContractEth == beforeContractEth
        assert(
            (!addReverted && afterUser == beforeUser + amount && afterContractEth == beforeContractEth + amount)
            ||
            (addReverted && afterUser == beforeUser && afterContractEth == beforeContractEth)
        );
    }

    // accept ETH when C sends funds back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes an amount to deposit and then tries to withdraw
    function run(uint deposit) public payable {
        require(address(this).balance >= deposit, "insufficient balance for deposit");
        // record before-values
        uint beforeReported = c.getBalance(address(this));
        uint beforeCbal = address(c).balance;

        // attempt to addToBalance sending `deposit` wei
        bool addReverted;
        try c.addToBalance{value: deposit}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        // record after addToBalance
        uint midReported = c.getBalance(address(this));
        uint midCbal = address(c).balance;

        // Now attempt to withdraw
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // record after withdraw
        uint afterReported = c.getBalance(address(this));
        uint afterCbal = address(c).balance;

        // General rule:
        // 1) If withdraw succeeded then reported balance for this address is zero.
        // 2) If withdraw succeeded then contract's ETH balance decreased by at most the reported balance just before withdraw (i.e., it did not send more than it held for that user).
        // 3) If withdraw reverted then reported and contract balances remain as before the withdraw attempt.
        assert(
            (
                (!withdrawReverted) && (afterReported == 0) && (midCbal - afterCbal <= midReported)
            )
            ||
            (
                (withdrawReverted) && (afterReported == midReported) && (afterCbal == midCbal)
            )
        );
    }

    // allow receiving ETH when C sends funds back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an amount to deposit then attempt withdraw
    function run(uint deposit) public payable {
        require(address(this).balance >= deposit);

        // Record C's balance for this contract before deposit
        uint beforeReported = c.getBalance(address(this));
        uint beforeCbal = address(c).balance;
        uint beforeThis = address(this).balance;

        // Perform deposit to C (may revert). We catch whether it reverted.
        bool depositReverted;
        try c.addToBalance{value: deposit}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // After deposit attempt, read reported balance and C's balance
        uint afterReported = c.getBalance(address(this));
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;

        // Now attempt withdraw; capture whether it reverted
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read final reported balance and balances
        uint finalReported = c.getBalance(address(this));
        uint finalCbal = address(c).balance;
        uint finalThis = address(this).balance;

        // General rule:
        // - If withdraw succeeded then the amount of ETH received by this contract equals
        //   the reported balance just before withdraw, and C's balance decreased by no less than that reported amount.
        // - If withdraw reverted then nothing changed by the withdraw: reported balance and ETH balances are the same as after the deposit attempt.
        assert(
            (!withdrawReverted && (finalThis - afterThis == afterReported) && (afterCbal - finalCbal >= afterReported) && finalReported == 0)
            || (withdrawReverted && finalReported == afterReported && finalCbal == afterCbal && finalThis == afterThis)
        );
    }

    // receive to accept ETH forwarded from C during withdraw
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Read before-values
        uint beforeReported = c.getBalance(address(this));
        uint beforeContractBal = address(c).balance;
        // Call addToBalance with amount and catch revert
        bool reverted;
        try c.addToBalance{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterReported = c.getBalance(address(this));
        uint afterContractBal = address(c).balance;
        // General rule: if reverted then no change; otherwise both values do not decrease
        assert(reverted ? (afterReported == beforeReported && afterContractBal == beforeContractBal)
                        : (afterReported >= beforeReported && afterContractBal >= beforeContractBal));
    }
    receive() external payable { }
}
